function VR_INTERLEAVING_DISTANCE(d1, d2, n):
    require IS_DIST_MATRIX(d1) and IS_DIST_MATRIX(d2)
    best <- 0
    for x in 0..n-1:
        for y in 0..n-1:
            gap <- |d1[x][y] - d2[x][y]|
            if gap > best:
                best <- gap
    return best        # = sup over ALL simplices, by edge-realization

function IS_DIST_MATRIX(d, n):
    for i in 0..n-1:
        if d[i][i] != 0: return false
        for j in 0..n-1:
            if d[i][j] < 0 or d[i][j] != d[j][i]: return false
    return true

